SELECT expected.id_user,coalesce(p.points,0) AS points,coalesce(p.total_points,0) AS total_points,coalesce(p.world_records,0)::integer AS world_records,expected.world_records AS expected_world_records,coalesce(p.personal_bests,0)::integer AS personal_bests,expected.personal_bests AS expected_personal_bests FROM zc_private.user_record_counts($1) expected LEFT JOIN public.user_points p ON p.id_user=expected.id_user
